package com.jinloes.practice;
import java.util.Arrays; import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: BST insertion values followed by the key, for example: [5,3,8,2,4,7,9] 6"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) { runInput(String.join(" ", args).trim()); return; } Solution.TreeNode root=tree(5,3,8,2,4,7,9); assertThat(Solution.firstGreater(root,6)).isEqualTo(7); assertThat(Solution.firstGreater(root,9)).isNull(); assertThat(Solution.firstGreater(root,4)).isEqualTo(5); System.out.println("Examples passed: 3"); } private static void runInput(String input){ try{ int end=input.indexOf(']'); int[] values=parse(input.substring(0,end+1)); int key=Integer.parseInt(input.substring(end+1).trim()); System.out.println(Solution.firstGreater(tree(values),key)); }catch(RuntimeException e){ System.out.println(USAGE); } } static int[] parse(String t){ String c=t.replace('[',' ').replace(']',' ').replace(',',' ').trim(); if(c.isEmpty()) return new int[0]; return Arrays.stream(c.split("\\s+")).mapToInt(Integer::parseInt).toArray(); } static Solution.TreeNode tree(int... values){ Solution.TreeNode root=null; for(int v:values) root=insert(root,v); return root; } static Solution.TreeNode insert(Solution.TreeNode n,int v){ if(n==null)return new Solution.TreeNode(v); if(v<n.value)n.left=insert(n.left,v); else n.right=insert(n.right,v); return n; } }
